CREATE OR REPLACE FUNCTION erp.post_accessory_reimbursement_accrual(p_lot_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE l erp.fg_lots%ROWTYPE;p erp.production_orders%ROWTYPE;v_hpp numeric(24,6);v_reimburse numeric(24,6);v_variance numeric(24,6);v_lines jsonb:='[]'::jsonb; BEGIN PERFORM erp.require_internal();PERFORM erp.ensure_fg_accessory_cost_snapshot(p_lot_id);SELECT * INTO l FROM erp.fg_lots WHERE id=p_lot_id; IF l.id IS NULL OR l.lot_origin<>'PRODUCTION' THEN RETURN; END IF;SELECT * INTO p FROM erp.production_orders WHERE id=l.po_id;SELECT COALESCE(SUM(total_hpp_cost),0),COALESCE(SUM(total_reimbursement),0) INTO v_hpp,v_reimburse FROM erp.fg_accessory_cost_snapshots WHERE lot_id=l.id; IF v_hpp=0 AND v_reimburse=0 THEN RETURN; END IF; IF EXISTS (SELECT 1 FROM erp.journal_entries WHERE source_type='ACCESSORY_REIMBURSE_ACCRUAL' AND source_id=l.id AND status='POSTED') THEN RETURN; END IF; IF v_reimburse>0 AND p.contractor_id IS NULL THEN RAISE EXCEPTION 'Accessory reimbursement requires PO contractor'; END IF; IF v_hpp>0 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','WIP','debit',round(v_hpp,2),'credit',0,'contractor_id',p.contractor_id,'po_id',p.id,'product_id',l.product_id)); END IF;v_variance:=v_reimburse-v_hpp; IF v_variance>0.005 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','ACCESSORY_REIMBURSE_VARIANCE','debit',round(v_variance,2),'credit',0,'contractor_id',p.contractor_id,'po_id',p.id,'product_id',l.product_id)); ELSIF v_variance< -0.005 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','ACCESSORY_REIMBURSE_VARIANCE','debit',0,'credit',round(abs(v_variance),2),'contractor_id',p.contractor_id,'po_id',p.id,'product_id',l.product_id)); END IF; IF v_reimburse>0 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',0,'credit',round(v_reimburse,2),'contractor_id',p.contractor_id,'po_id',p.id,'product_id',l.product_id)); END IF; IF v_reimburse=0 AND v_hpp>0 THEN RAISE EXCEPTION 'Accessory HPP snapshot has cost but zero mandor reimbursement; configure reimbursement or use normal material issue flow'; END IF; IF jsonb_array_length(v_lines)>=2 THEN PERFORM erp.post_journal('ACCESSORY_REIMBURSE_ACCRUAL',l.id,l.produced_at::date,'Accessory HPP basis + mandor reimbursement entitlement from GOOD FG',v_lines); END IF; END; $function$;

alter function "erp"."post_accessory_reimbursement_accrual"(p_lot_id uuid) owner to "postgres";
